export const addPhoto = async (id: string,
    addPhotoBody: AddPhotoBody, options?: Parameters<typeof http>[1]): Promise<addPhotoResponse> => {
    const formData = new FormData();
if(addPhotoBody.role !== undefined) {
 formData.append(`role`, addPhotoBody.role);
 }
if(addPhotoBody.width !== undefined) {
 formData.append(`width`, addPhotoBody.width.toString())
 }
if(addPhotoBody.height !== undefined) {
 formData.append(`height`, addPhotoBody.height.toString())
 }
formData.append(`original`, addPhotoBody.original);
formData.append(`ai`, addPhotoBody.ai);

  return http<addPhotoResponse>(getAddPhotoUrl(id),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}



